// True when `insn` appears in any Program-Buffer slot of the recorded ops.
auto pb_has_insn(const std::vector<DmiOp>& ops, uint32_t insn) -> bool
{
  for (const auto& op : ops)
    if (op.kind == DmiOp::Kind::Write
        && op.reg >= hybrid::kProgbuf0
        && op.reg <= hybrid::kProgbuf0 + hybrid::kProgbufMaxInsns
        && op.value == insn)
      return true;
  return false;
}

}  // namespace

